    boxShadow: '0 2px 4px rgba(0,0,0,0.08)',
    marginBottom: '20px'
  },
  title: {
    fontSize: '28px',
    marginBottom: '5px'
  },
  subtitle: {
    color: '#666',
    fontSize: '14px'
  },
  form: {
    background: 'white',
    borderRadius: '12px',
    padding: '30px',
    boxShadow: '0 2px 4px rgba(0,0,0,0.08)'
  },
  section: {
    marginBottom: '30px'
  },
  sectionTitle: {
    fontSize: '18px',
    marginBottom: '5px',
    color: '#333'
  },
  sectionSubtitle: {
    fontSize: '14px',
    color: '#666',
    marginBottom: '15px'
  },
  formGroup: {
    display: 'flex',
    flexDirection: 'column',
    gap: '5px',
    marginBottom: '15px'
  },
  label: {
